import yaml,re
d=yaml.safe_load(open('.coordination/mining/v2/day-005.yaml'))
src=open('claude-dev-log-diary/day-005.md').read()
def norm(s): return re.sub(r'\s+',' ',s).strip()
nsrc=norm(src)
items=[]
for sec in ['philosophy','skill_rules','failure_modes','pairing_rules']:
    for it in d[sec]:
        q=it.get('quote')
        if q: items.append((sec, it.get('rule_id') or it.get('name') or str(it.get('statement'))[:25], q))
        ui=it.get('user_intervention')
        if ui and '"' in str(ui): items.append((sec+'/ui', it.get('name'), ui))
miss=[]
for sec,ident,q in items:
    # split on elision markers and quote-wrappers
    parts=re.split(r'\.\.\.|…|\\n|\n', q)
    for p in parts:
        p=p.strip().strip('"').strip()
        p=re.sub(r'\(L\d+[^)]*\)$','',p).strip().strip('"').strip()
        p=re.sub(r'^\[.*?\]$','',p).strip()
        if len(p)<12: continue
        if norm(p) not in nsrc:
            miss.append((sec,ident,p[:110]))
print('UNVERIFIED FRAGMENTS:', len(miss))
for m in miss: print(m)
